fn compute_page_step(&self) -> usize {
        // Derive the page step from the most recently rendered list area: divide
        // the visible row capacity by the estimated average item height, then
        // clamp to [SESSION_PAGE_MIN_STEP, visible_rows] so the user always sees
        // at least partial overlap.
        if self.list_visible_rows == 0 {
            return 1;
        }
        let item_count = self.item_to_session.iter().filter(|x| x.is_some()).count();
        if item_count == 0 {
            return 1;
        }
        self.list_visible_rows
            .div_ceil(DEFAULT_ITEM_HEIGHT_ESTIMATE)
            .max(SESSION_PAGE_MIN_STEP)
            .min(self.list_visible_rows)
    }

    fn focus_previous_page(&mut self) {
        match self.focus {
            PaneFocus::Sessions => {
                let step = self.compute_page_step();
                for _ in 0..step {
                    self.previous();
                }
            }
            PaneFocus::Preview => {
                self.scroll_preview_up(PREVIEW_PAGE_SCROLL);
            }
        }
    }

    fn focus_next_page(&mut self) {
        match self.focus {
