use ratatui::widgets::Wrap;

/// Truncate a string to at most `max_display_width` terminal cells, appending
/// "..." when truncation occurs. Zero-width, wide, and combining characters are
/// measured correctly (unlike the legacy char-count truncation in
/// `safe_truncate`).
fn truncate_to_display_width(s: &str, max_display_width: usize) -> String {
    let full_width = unicode_width::UnicodeWidthStr::width(s);
    if full_width <= max_display_width {
        return s.to_string();
    }
    let ellipsis = "...";
    let ellipsis_width: usize = unicode_width::UnicodeWidthStr::width(ellipsis);
    if max_display_width < ellipsis_width {
        // Not enough room for ellipsis; just truncate to zero characters.
        return String::new();
    }
    let budget = max_display_width - ellipsis_width;
    let mut result = String::new();
    let mut used = 0usize;
    for ch in s.chars() {
        let cw = unicode_width::UnicodeWidthChar::width(ch).unwrap_or(0);
        if used + cw > budget {
            break;
        }
        result.push(ch);
        used += cw;
    }
    result.push_str(ellipsis);
    result
}

