pub(super) fn render_session_item_lines_at_frame(
        &self,
        session: &SessionInfo,
        is_selected: bool,
        spinner_frame: usize,
    ) -> Vec<Line<'static>> {
        let dim: Color = rgb(100, 100, 100);
        let dimmer: Color = rgb(70, 70, 70);
        let user_clr: Color = rgb(138, 180, 248);
        let batch_restore: Color = rgb(255, 140, 140);

        let activity_ago = format_time_ago(session.last_message_time);
        let in_batch_restore = self.crashed_session_ids.contains(&session.id);
        let is_marked = self.selected_session_ids.contains(&session.id);
        let same_dir = self.session_in_current_dir(session);
        let same_dir_clr: Color = rgb(120, 200, 140);
        let highlight_tokens = self.active_highlight_tokens();

        let name_style = if is_selected {
            Style::default()
                .fg(rgb(140, 220, 160))
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(Color::White)
        };

        let selection_marker = if is_marked { "● " } else { "○ " };
        let selection_style = if is_marked {
            Style::default()
                .fg(rgb(140, 220, 160))
                .add_modifier(Modifier::BOLD)
        } else {
            Style::default().fg(rgb(90, 90, 90))
        };

        // Determine the compact live/status icon + label for line 3.
        let is_current = self.session_is_current(session);
        let live_badge = if self.session_is_live(session) {
            if session.source == SessionSource::ClaudeCode {
                Some(("●", "live Claude"))
            } else if self.session_is_streaming(session) {
                let label = match self.session_streaming_duration(session) {
                    Some(elapsed) => format!("working {}", format_short_duration(elapsed)),
                    None => "working".to_string(),
                };
                Some((
                    jcode_tui_render::swarm_gallery::STRIP_SPINNER_FRAMES[spinner_frame
                        % jcode_tui_render::swarm_gallery::STRIP_SPINNER_FRAMES.len()],
                    &label,
                ))
            } else {
                Some(("●", "ready"))
            }
        } else {
            None
        };
        let status_icon = match live_badge {
            Some((icon, _)) => icon.to_string(),
            None => match &session.status {
                SessionStatus::Active => "▶".to_string(),
                SessionStatus::Closed => "✓".to_string(),
                SessionStatus::Crashed { .. } => "💥".to_string(),
                SessionStatus::Reloaded => "🔄".to_string(),
                SessionStatus::Compacted => "📦".to_string(),
                SessionStatus::RateLimited => "⏳".to_string(),
                SessionStatus::Error { .. } => "❌".to_string(),
            },
        };
        let status_label = match live_badge {
            Some((_, label)) => label.to_string(),
            None => match &session.status {
                SessionStatus::Active => "active".to_string(),
                SessionStatus::Closed => "closed".to_string(),
                SessionStatus::Crashed { .. } => "crashed".to_string(),
                SessionStatus::Reloaded => "reloaded".to_string(),
                SessionStatus::Compacted => "compacted".to_string(),
                SessionStatus::RateLimited => "rate-limited".to_string(),
                SessionStatus::Error { .. } => "errored".to_string(),
            }
            .to_string(),
        };

        // ── Line 1: selection · icon · title · right-aligned activity age ──
        let primary_title = Self::primary_title_display(session);
        let mut line1_spans = vec![
            Span::styled(selection_marker, selection_style),
            Span::styled(
                format!("{} ", session.icon),
                Style::default().fg(rgb(110, 210, 255)),
            ),
        ];
        line1_spans.extend(Self::highlight_spans(
            &primary_title,
            &highlight_tokens,
            name_style,
        ));
        // Right-pad title so the activity age is right-aligned.
        line1_spans.push(Span::styled(
            format!(" {}", activity_ago),
            Style::default().fg(dimmer),
        ));
        let line1 = Line::from(line1_spans).right_aligned();

        // ── Line 2: context excerpt (search hit or first user prompt) ──
        let mut excerpt = String::new();
        // When searching, prefer the matched content from the title/prompt; the
        // first-user-prompt is the best textual preview we can show per-row
        // without loading every full transcript synchronously.
        if let Some(prompt) = session.first_user_prompt.as_deref().map(str::trim)
            && !prompt.is_empty()
        {
            excerpt = prompt.replace('\n', " ");
            // Let the excerpt use the full row width minus the lead-in indent.
            excerpt = truncate_to_display_width(&excerpt, 100);
        }
        let line2 = if excerpt.is_empty() {
            Line::from(vec![Span::styled(
                "     (empty session)",
                Style::default().fg(dimmer),
            )])
        } else {
            let mut prompt_spans = vec![Span::styled("     ", Style::default())];
            prompt_spans.extend(Self::highlight_spans(
                &excerpt,
                &highlight_tokens,
                Style::default().fg(rgb(180, 180, 220)),
            ));
            Line::from(prompt_spans)
        };

        // ── Line 3: project · badges · status ──
        let mut badge_parts: Vec<&str> = Vec::new();

        // Project/directory identity first.
        if let Some(ref dir) = session.working_dir {
            if let Some(base) = std::path::Path::new(dir).file_name().and_then(|n| n.to_str()) {
                badge_parts.push(base);
            }
        } else {
            badge_parts.push("jcode");
        }

        // Source badge for external tools.
        if session.source != SessionSource::Jcode {
            if let Some(b) = session.source.badge() {
                badge_parts.push(b);
            }
        }

        // Saved marker.
        if session.saved {
            badge_parts.push("📌 saved");
        }

        // Current-directory indicator.
        if same_dir {
            badge_parts.push("▸ here");
        }

        // Current-session indicator.
        if is_current {
            badge_parts.push("◀ current");
        }

        // Live/status icon.
        badge_parts.push(&status_icon);
        badge_parts.push(&status_label);

        // Batch restore badge.
        if in_batch_restore {
            badge_parts.push("[BATCH]");
        }

        let badge_line = badge_parts.join(" · ");
        let line3 = Line::from(vec![
            Span::styled("     ", Style::default()),
            Span::styled(badge_line, Style::default().fg(dimmer)),
        ]);

        vec![line1, line2, line3]
    }

