/// Sort order for the session picker list. Separate from filtering so users
/// can independently decide what to show (filter) and how to order it (sort).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub enum SessionSortMode {
    /// Most recently active first (default). Matches the primary use case of
    /// resuming where you left off. Equivalent to fzf's `--scheme=history`.
    Recency,
    /// Alphabetical by title, with recency as tiebreaker.
    Title,
    /// Saved/bookmarked sessions first, then unsaved, each group in recency
    /// order.
    SavedFirst,
    /// Newest creation date first.
    Creation,
    /// Relevance order: match quality determines position. Automatically
    /// selected when a search query is active; reverts to recency when the
    /// query is cleared.
    Relevance,
}

impl SessionSortMode {
    pub fn next(self) -> Self {
        match self {
            Self::Recency => Self::Title,
            Self::Title => Self::SavedFirst,
            Self::SavedFirst => Self::Creation,
            Self::Creation => Self::Recency,
            // Relevance is not part of the user-facing cycle; it's selected
            // automatically when searching.
            Self::Relevance => Self::Recency,
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Recency => "recency",
            Self::Title => "title",
            Self::SavedFirst => "saved",
            Self::Creation => "creation",
            Self::Relevance => "relevance",
        }
    }
}

impl Default for SessionSortMode {
    fn default() -> Self {
        Self::Recency
    }
}

