fn filtered_session_refs(
        &self,
        search_matches: &[SessionRef],
        show_test: bool,
        filter_mode: SessionFilterMode,
    ) -> Vec<SessionRef> {
        let mut filtered = search_matches
            .iter()
            .copied()
            .filter(|session_ref| {
                self.session_by_ref(*session_ref).is_some_and(|session| {
                    (show_test || !session.is_debug)
                        && self.session_matches_filter_mode(session, filter_mode)
                })
            })
            .collect::<Vec<_>>();

        // Active mode always uses a special triage sort: ready sessions float
        // above working ones, each group sorted by the active sort mode.
        if filter_mode == SessionFilterMode::Active {
            let active_sort = self.sort_mode;
            let reversed = self.sort_reversed;
            filtered.sort_by(|a, b| {
                let a_streaming = self
                    .session_by_ref(*a)
                    .map(|s| self.session_is_streaming(s))
                    .unwrap_or(false);
                let b_streaming = self
                    .session_by_ref(*b)
                    .map(|s| self.session_is_streaming(s))
                    .unwrap_or(false);
                // Ready (false) sorts before working (true).
                let streaming_cmp = a_streaming.cmp(&b_streaming);
                if streaming_cmp != std::cmp::Ordering::Equal {
                    return streaming_cmp;
                }
                Self::cmp_sessions(self, *a, *b, active_sort, reversed)
            });
            return filtered;
        }

        Self::sort_sessions(self, &mut filtered, self.sort_mode, self.sort_reversed);
        filtered
    }

    /// Sort a mutable slice of session refs using the given sort mode and
    /// direction.
    fn sort_sessions(
        slf: &SessionPicker,
        refs: &mut [SessionRef],
        mode: SessionSortMode,
        reversed: bool,
    ) {
        refs.sort_by(|a, b| Self::cmp_sessions(slf, *a, *b, mode, reversed));
    }

    /// Compare two session refs using the given sort mode and direction.
    fn cmp_sessions(
        slf: &SessionPicker,
        a: SessionRef,
        b: SessionRef,
        mode: SessionSortMode,
        reversed: bool,
    ) -> std::cmp::Ordering {
        let cmp = match mode {
            SessionSortMode::Recency => {
                let a_time = slf
                    .session_by_ref(a)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                let b_time = slf
                    .session_by_ref(b)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                b_time.cmp(&a_time)
            }
            SessionSortMode::Title => {
                let a_title = slf
                    .session_by_ref(a)
                    .map(|s| s.title.trim().to_lowercase())
                    .unwrap_or_default();
                let b_title = slf
                    .session_by_ref(b)
                    .map(|s| s.title.trim().to_lowercase())
                    .unwrap_or_default();
                let title_cmp = a_title.cmp(&b_title);
                if title_cmp != std::cmp::Ordering::Equal {
                    return if reversed {
                        title_cmp.reverse()
                    } else {
                        title_cmp
                    };
                }
                // Tie-break by recency.
                let a_time = slf
                    .session_by_ref(a)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                let b_time = slf
                    .session_by_ref(b)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                b_time.cmp(&a_time)
            }
            SessionSortMode::SavedFirst => {
                let a_saved = slf.session_by_ref(a).map(|s| s.saved).unwrap_or(false);
                let b_saved = slf.session_by_ref(b).map(|s| s.saved).unwrap_or(false);
                let saved_cmp = b_saved.cmp(&a_saved); // true (saved) sorts before false
                if saved_cmp != std::cmp::Ordering::Equal {
                    return if reversed {
                        saved_cmp.reverse()
                    } else {
                        saved_cmp
                    };
                }
                // Tie-break by recency.
                let a_time = slf
                    .session_by_ref(a)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                let b_time = slf
                    .session_by_ref(b)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                b_time.cmp(&a_time)
            }
