                // search). Fall back to recency if misused.
                let a_time = slf
                    .session_by_ref(a)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                let b_time = slf
                    .session_by_ref(b)
                    .map(|s| s.last_message_time)
                    .unwrap_or_default();
                b_time.cmp(&a_time)
            }
        };
